// What to repurchase and when. units_recommended is the quantity the renewal options recommend, the same number the drawer shows: 0 with decision let_expire when the commitment was used too little to pay for itself, the quantity held when nothing measured it. units_consumed is the average the sized series measured, null when unmeasured. States the instant to buy after rather than a date, because a replacement bills from the moment it is bought, and lists the pending changes to the same instance family that must land first so their capacity is not reserved for another term. superseded_by names the commitment that already renewed this one, and no_recent_usage says nothing of its family and engine ran last week; either one means no renewal is raised.
func (c *Client) GetRenewalPlan(
	ctx context.Context,
	commitmentID string,
	opts ...option.RequestOption,
) (*levelfour.RenewalPlanResponse, error) {
	response, err := c.WithRawResponse.GetRenewalPlan(
		ctx,
		commitmentID,
		opts...,
	)
	if err != nil {
		return nil, err
	}
	return response.Body, nil
}

// Azure's own reservation and savings plan recommendations over the last 30 days, read by the Azure connection's daily sync. Azure prices them at its own rates, so only its saving as a share of cost is kept and applied to what the covered usage cost on demand on the bill over the same 30 days: the meter and region for a reservation, the compute services for a savings plan. unavailable_reason is no_bill when that usage cost nothing on demand. raised_recommendation_id names the undecided BUY- purchase already raised for a proposal. Never calls Azure.
func (c *Client) GetAzurePurchasePlan(
	ctx context.Context,
	opts ...option.RequestOption,
) (*levelfour.AzurePurchasePlanResponse, error) {
	response, err := c.WithRawResponse.GetAzurePurchasePlan(
		ctx,
		opts...,
	)
	if err != nil {
		return nil, err
	}
	return response.Body, nil
}

// Raises one /azure/purchase-plan proposal as a BUY- savings recommendation. Nothing is bought until an organization admin releases it, so a member may raise one, and so may a read-write API key. Raising a proposal again returns the purchase nobody has decided yet for it with created false. One awaiting approval, accepted, released, failed but retryable, or bought in the last 24 hours is answered 409 same_purchase_exists with that purchase's recommendation_id, state, raised_by and raised_at; send it again with confirm_additional true to raise a second one. A proposal whose usage cost nothing on demand is refused with 409, since it has no saving on the bill. The row carries the term total it is accepted at, and a released Azure purchase is bought by the LevelFour operator under a grant for that one purchase, never at materially more, or by hand.
func (c *Client) PostAzurePurchase(
	ctx context.Context,
	request *levelfour.AzurePurchaseRaise,
	opts ...option.RequestOption,
) (*levelfour.AzurePurchaseRaisedResponse, error) {
	response, err := c.WithRawResponse.PostAzurePurchase(
		ctx,
		request,
		opts...,
	)
	if err != nil {
		return nil, err
	}
	return response.Body, nil
}

